// iOS launch screens (public/splash, generated by scripts/gen-icons.mjs).
// iOS picks the one whose media query matches the device exactly; portrait
// only, since the app is used upright. [width, height, pixel ratio].
const SPLASH_SCREENS: [number, number, number][] = [
  [1320, 2868, 3], // 16/17 Pro Max
  [1206, 2622, 3], // 16/17 Pro, 17
  [1260, 2736, 3], // Air
  [1290, 2796, 3], // 14 Pro Max, 15/16 Plus, 15 Pro Max
  [1179, 2556, 3], // 14 Pro, 15, 15 Pro, 16
  [1284, 2778, 3], // 12/13 Pro Max, 14 Plus
  [1170, 2532, 3], // 12, 13, 14, 12/13 Pro
  [1125, 2436, 3], // X, XS, 11 Pro, 12/13 mini
  [1242, 2688, 3], // XS Max, 11 Pro Max
  [828, 1792, 2], // XR, 11
  [750, 1334, 2], // SE, 6/7/8
]

export const startupImages = SPLASH_SCREENS.map(([w, h, r]) => ({
  url: `/splash/${w}x${h}.png`,
  media: `(device-width: ${w / r}px) and (device-height: ${h / r}px) and (-webkit-device-pixel-ratio: ${r}) and (orientation: portrait)`,
}))
